enum_members = [
    en("CM550", 17, "FUELING_STATE_UNIDENTIFIED_17", "FUELING_STATE_ACCELERATION_NOISE_CONTROL_DERATE",
       "torque_derate_fuel_source_code (cm550_applyAccelerationNoiseControlFuelLimit 0xb3b2): acceleration_noise_control_fuel_limit (e2m 10A4 +0 NZFLLM 'fueling limit as determined by the ANC feature') is below the running derate minimum - Calterm FSFNFLST 11=ANCDERAT (no CM848 member: CM848 has no such limiter)",
       "move.w #0x11,(0x80deca).l at 0xb3c6 after cmp.w / bcc on NZFLLM 0x80a28c against FSLMFL 0x80dec8 - the only store of 17 into a fueling state word (scan of every move.w #17). e2m v64t6_s: group ACCNOISE 'ACCELERATION NOISE CONTROL GROUP' holds the NZ* records; NZFLAGEN 'ENABLE FOR FUEL LIMITING OF THE ACCELERATION NOISE C(ONTROL)'; the repository already expands ANC this way (algorithm_enable_flags_3_cal.acceleration_noise_control_timing_limit_enable).",
       "high"),
    en("CM550", 33, "FUELING_STATE_UNIDENTIFIED_33", "FUELING_STATE_ENGINE_WARMUP_PROTECTION",
       "torque_derate_fuel_source_code (cm550_applyEngineWarmupProtectionFuelLimit 0x17120): with engine_state RUNNING and engine_warmup_protection_fuel_limiting_flag (e2m 11EA +0 WPLMFG) set - engine_warmup_protection_fuel_limit (11EA +14 WPTQLM) is below the running derate minimum. The warmup protection limits the fuel after a start until the oil pressure has been up long enough - Calterm FSFNFLST 21=ESUOILLM (no CM848 member)",
       "move.w #0x21,(0x80deca).l at 0x17146 behind cmpi.w #0x3,(0x80d0c8).l (0x1712c), tst.w (0x80ccb2).l (0x17136) and cmp.w / bcc on WPTQLM 0x80ccc6 - the only store of 33 into a fueling state word. e2m group EWP_HDR 'ENGINE WARMUP PROTECTION GROUP': WPLMFG 'FUEL IS BEING LIMITED BY ENGINE WARMUP PROTECTION WHEN 1', WPTQLM 'CALCULATED TORQUE LIMIT OF ENGINE STARTUP SPEED LIMIT ALGORITH(M)', WPO2TDCN 'CALIBRATIBLE THRESHOLD FOR RIFLE OIL PRESSURE FOR ENGINE WARMU(P)', WPEAFG 'ENABLE ENGINE WARMUP PROTECTION ALGORITHM WORD 12 BIT 1' (the bit the state machine 0x16dd4 tests at 0x16df0).",
       "high"),
    en("CM550", 18, "FUELING_STATE_UNIDENTIFIED_18", "FUELING_STATE_ENGINE_PROTECTION",
       "only compared - never stored in the dumped ROM: cm550_rpmHistogramAndAveragingStatistics counts the trip record 1216 +6C TIT3DQTM 'time the fueling has been under control of engine protection since last trip reset' (dword 0x806192) while final_fueling_state is 18. The engine protection fuel derate itself stamps 29 (FUELING_STATE_FAULT_DERATE - Calterm EPFDERAT), so with the dumped code that counter cannot advance; 18 is another code of the same feature family - Calterm FSFNFLST 12=EPF (no CM848 member)",
       "cmpi.w #0x12,(0x80d330).l at 0x306b4 ; bne ; addq.l #1,(0x806192).l at 0x306be (function 0x304f4; the 0x3061a row is a mid-body duplicate); the trip reset clears the counter (clr.l at 0x3077a). The only other use is the EEC1 torque mode jump table 0x32d04 (entry 18 in the 0xF8 torque limiting group). No immediate store of 18 into a fueling state word (scan: the two move.w #18 hits are the executive phase 0x80068c and a governor gain word 0x80d61a). e2m: EPEN 'ENGINE PROTECTION FEATURES ENABLE', EPFLLM 'MAXIMUM FUELING PERMITTED BY THE ENGINE PROTECTION FEATURES', the 'EPF CHANNEL ...' records.",
       "medium"),
    en("both", 37, "FUELING_STATE_UNIDENTIFIED_37", "FUELING_STATE_TOP2_TRANSMISSION_SPEED_CONTROL",
       "only compared - never stored in either firmware. A speed control state of the Top2 transmission feature: CM848's all-speed governor runs while engine_operating_mode is 7 / 2 / 30 / 37, and 37 is tested with 38 beside the TSC1 states 1 / 2 in the power take-off - cruise - governed fueling and driver demand selection; both EEC1 torque mode tables put 37 with the accelerator pedal states. e2m group TOP208 'TOP2 CALIBRATIONS AND DATA' holds the T2* records (T2HGSXDR 'TOP2 SPICER TRANSMISSION HIGH GEAR DRIVER SOLENOID') - Calterm FSFNFLST 25=T2SPD (was FUELING_STATE_UNIDENTIFIED_37)",
       "CM848: cmpwi r29,37 at 0xea3c in cm848_runOperatingModeSpeedGovernor (after 7 at 0xea24, 2 at 0xea2c, 30 at 0xea34: the governor runs in these four states); cmpwi 37 / 38 at 0x2bc04 / 0x2bc0c (cm848_selectPowerTakeOffOrUserFueling: 1 / 2 / 37 / 38 pass the user fueling through), 0x412c4 / 0x412cc (cm848_selectCruiseOrUserFueling), 0x407b8 / 0x407c0 (cm848_arbitrateGovernedFueling), 0x208fc / 0x20904 (cm848_calculateDriverDemandPercentTorque), 0x5253f4 / 0x5253fc and 0x5255c4 / 0x5255cc (the cruise governor); EEC1 0x2588c case 0x25 -> 0xF1. No li 37 reaches a fueling state word in either image (the one li 37 is the executive phase at 0xc748). CM550: only the EEC1 jump table 0x32d04 (entry 37 -> 0x32d5c with 1 / 2 / 3 / 7 / 8 / 30: torque mode 0xF1 / 0xFB); no immediate store of 37 into a fueling state word (the one move.w #37 is the executive phase); e2m ASRFST range '2,3,7,30,37' (the states that control the ASG reference). T2 = Top2: v64t6_s group TOP208 and T2HGSXDR / T2LGSXDR / T2NUSXDR 'TOP2 SPICER TRANSMISSION ... DRIVER SOLENOID', T2SISXDR '0=(1 GEAR DOWN OR BELOW)/1=(TOP GEAR)'; CHR e2m T2_High_Gear_Driver / T2_Shift_Driver / T2_Lockout_Driver / T2_Gear_Position_Sensor.",
       "medium"),
    en("both", 38, "FUELING_STATE_UNIDENTIFIED_38", "FUELING_STATE_TOP2_TRANSMISSION_TORQUE_CONTROL",
       "only compared - never stored in either firmware. The torque control state of the Top2 transmission feature: CM848 tests it with 37 beside the TSC1 states 1 / 2 (power take-off - cruise - governed fueling - driver demand selection) but its all-speed governor does not run in 38 - as it does not in TSC1 torque control (1). CM550 has it only in the EEC1 torque mode table, in the torque limiting group - Calterm FSFNFLST 26=T2TORQ (was FUELING_STATE_UNIDENTIFIED_38)",
       "CM848: cmpwi 38 at 0x2bc0c, 0x412cc, 0x407c0, 0x20904, 0x5253fc, 0x5255cc - each directly after the test of 37 and in the same branch as 1 and 2; cm848_runOperatingModeSpeedGovernor 0xea00 tests 7 / 2 / 30 / 37 only. No li 38 reaches a fueling state word (the li 38 sites are output numbers and the executive phase at 0xc764). CM550: EEC1 jump table 0x32d04 entry 38 -> 0x32d88 (move.b #0xf8: torque limiting) with 13-21 / 28 / 29 / 31 / 33-36 / 39-41; no immediate store of 38 into a fueling state word. T2 = Top2 as for 37.",
       "medium"),
    en("CM550", 3, "FUELING_STATE_UNIDENTIFIED_3", "FUELING_STATE_UNIDENTIFIED_3",
       "only compared - never stored in the dumped ROM: the all-speed governor runs while user_fueling_state is 7 / 3 / 2 / 30 - the power take-off selection passes 1 / 2 / 30 / 3 through - the driver demand uses the 4D fueling in 8 / 3 / 7 - and the EEC1 torque mode table puts 3 with the accelerator pedal states. So 3 is a user speed control state through the all-speed governor (e2m ASRFST range 2,3,7,30,37). The label's PS is probably progressive shift (PSAGEN 'enable/disable Prog. Shift feature' in group PRGSHFT2 'PROGRESSIVE SHIFT GROUP') but nothing in the ROM ties that feature to state 3 - Calterm FSFNFLST 3=PSSPEED (no CM848 member; CM848's EEC1 table still has case 3)",
       "cmpi.w #0x3,(0x80ded4).l at 0xc982 (cm550_runAllSpeedGovernor), cmpi.w #0x3,(a2 = 0x80ded4) at 0x2dcde (function 0x2dcb0), cmpi.w #0x3,(a2 = 0x80a8f2) at 0xf7f6 (function 0xf796), EEC1 jump table 0x32d04 entry 3 -> 0x32d5c. No immediate store of 3 into any fueling state word (scan of all 27 move.w #3: timing state, alpha state, engine_state, JCEGMD and others). The ASG reference state 0x80a98e only takes 30 / 2 / 7 (0xd0f8 / 0xd22c / 0xd598). PSAGEN is bit 0x20 of algorithm_enable_flags_0_cal and no direct test uses that mask (the tests of 0x803c94 use 0x40 / 0x100 / 0x400-0x8000); JCPSDB 0x80da58 'JCOMM PROGRESSIVE SHIFT DISABLE' is only written and timed (0x2f09c / 0x2f0be / 0x2330c-0x2332a), with no reader near a state 3 test. Other PS expansions exist in the e2m family (PSLH* 'PRESS SENSOR LIMPHOME', PSPEN 'POWERSPEC'), so the label alone does not prove the meaning: kept.",
       "high"),
    en("CM550", 36, "FUELING_STATE_UNIDENTIFIED_36", "FUELING_STATE_UNIDENTIFIED_36",
       "no dumped code stores it or tests it on its own (only the EEC1 torque mode jump table - in the torque limiting group). The label reads powertrain protection derate: e2m group PTP_07 'GROUP CONTAINING ELECTRONIC CONSTANTS FOR POWERTRAIN PROTECTION' with 12B4 +0 TCFL 'POWERTRAIN PROTECTION FUELING' (0x80dc46) - but no instruction reads TCFL in the dumped ROM; its limiter may be one of the two undumped calls of cm550_runFuelLimitChains (0x45252 / 0x455c8) - Calterm FSFNFLST 24=PTPDERAT (no CM848 member)",
       "No immediate store of 36 into a fueling state word (scan: the one move.w #36 is the executive phase word 0x80068c at 0x1be0a) and no cmpi.w #36 on one; EEC1 jump table 0x32d04 entry 36 -> 0x32d88 (0xF8). abs_refs 0x80dc46 (TCFL): only the parameter table at 0x3693c / 0x36940. e2m: TCEN 'POWERTRAIN PROTECTION ENABLE WORD 19H, BIT 1', CHR 'PTP_Enable [TCEN]', later label 39=JCPTPDER. The letters PTP also start the PTO PID mnemonics PTPPGN / PTPPFL / PTPDFL (blocks 10AA / 10AB), so the reading rests on the label alone: kept.",
       "high"),
    en("CM550", 39, "FUELING_STATE_UNIDENTIFIED_39", "FUELING_STATE_UNIDENTIFIED_39",
       "no dumped code stores it or tests it on its own (only the EEC1 torque mode jump table - in the torque limiting group). By its label it is the derate of the Top2 transmission feature (see 37 / 38: e2m group TOP208 'TOP2 CALIBRATIONS AND DATA') but no code shows its limit; it may be one of the two undumped calls of cm550_runFuelLimitChains - Calterm FSFNFLST 27=T2DERAT (no CM848 member)",
       "No immediate store of 39 into a fueling state word (scan: the move.w #39 hits are the executive phase word at 0x1be66 and a hardware register at 0x1bf98) and no cmpi.w #39 on one; EEC1 jump table 0x32d04 entry 39 -> 0x32d88 (0xF8). No e2m record names a Top2 fuel limit: kept.",
       "high"),
]

summary = ("CM550's torque derate fuel limit chain has the same design as CM848's: a runner (0x30c3c - counterpart of CM848 0x4280c) calls an initializer and one small limiter per derate source, and each limiter compares its limit record with the running minimum FSLMFL (e2m 105D +0 - CM848's torque_derate_fuel_quantity) or the group 2 air handling minimum (105D +6) and stamps its FUELING_STATE number. "
           "Seven of the nine dumped steps are instruction-for-instruction twins of CM848 functions (initializer 19 / 40, power take-off torque limit 34, air fuel control 16, altitude 15, fault derate 29, TSC1 torque limit 20, fuel system derate 28); two exist only in CM550 and name their members: the acceleration noise control fuel limit (17 - Calterm ANCDERAT) and the engine warmup protection fuel limit (33 - ESUOILLM). "
           "The runner's only caller 0x1c152 is the final fueling selection (requested fueling - engine state overrides - clamp): CM848's cm848_arbitrateRequestedFueling plus cm848_selectFinalFueling in one function. "
           "The second chain (0x30b34) is not a fuel chain: it is the injection timing modification chain on TSOI (e2m 103B +2) - misfire limit, AFC advance, cylinder pressure maintenance increment, wet stack advance, ANC limit, maximum limit and cranking timing - each stamping the Calterm timing state. "
           "The remaining functions are unrelated to the chains: the fuel shutoff driver command, two start-up initializers (idle adjustment and trip information), the hour meter task (twin of cm848_advanceHourMeters) and an empty stub (skipped). "
           "Of the other unidentified members 18 / 37 / 38 get names from the code that compares them plus the e2m (never stored), and 3 / 36 / 39 stay unidentified with the reading in the comment.")

notes = ("ENUM MEMBERS. Scans behind the 'never stored' wording: scratch scan_cm550_state_constants.py (every move.w #N / cmpi.w #N / moveq form with 3, 18, 36-39 against the nine typed carriers plus the untyped 0x80d33a and 0x80a98e) and scan_cm848_state_constants.py (every li / cmpwi / cmplwi with 37, 38, 49, 50 in both images). A store through a register copy cannot be excluded by a scan, and the undumped CM550 code (0x45252, 0x455c8, 0x49f32 are called from these chains) may store 3 / 18 / 36 / 39. "
         "3 PSSPEED, 36 PTPDERAT and 39 T2DERAT are kept: the readings (progressive shift speed control; powertrain protection derate; Top2 transmission derate) rest on label prefixes, and PS and PTP have other expansions in the e2m family. If 37 / 38 are accepted as Top2, 39 is the same prefix and could follow as FUELING_STATE_TOP2_TRANSMISSION_DERATE. "
         "CM848 49 OFCSTATE and 50 AFRSTATE stay: only compared (49 at 0xee74 / 0xf548 in cm848_runOperatingModeSpeedGovernor with 16 / 19; 50 at 0x52a48c in cm848_calculateFuelPressureSetpoint with 16 / 58), no li 49 anywhere and no li 50 into a fueling state word - a class (air limited fueling), not an algorithm. CM848's enum header comment lists '(37 38 49 50)' as unidentified and the comment of 37 guesses a two-speed axle: both need the Top2 wording if 37 / 38 are renamed. CM848's EEC1 table has a case 3 (0xF1 group) though its enum has no member 3. "
         "RUNNER RELATION. 0x30c3c / 0x4280c are reported as counterparts because the step lists differ; if a build-specific call list counts as the same function the shared name would be runFuelLimitChains. Either way CM848's cm848_processProtectionLimits (0x4280c) and cm848_calculateProtectionRateLimited (0x1e4e8) carry the bare word protection: cm848_runFuelLimitChains and - for 0x1e4e8 with CM550 0x1c0d4 - applyTorqueDerateTorqueLimit would fit. "
         "LEADS OUTSIDE THE BATCH. 0x1c0d4 cm550_FUN_0001c0d4 = CM848 0x1e4e8: converts the torque limit TQDQTQ into fuel (TQDQTQ x (FSMTFLNP 0x80d370 - NLFL 0x80db1c) / MTMPRPFL 0x80db1a + NLFL, floor 0), lowers FSLMFL with the state TQDQTQST, then resets TQDQTQ = 0xFFFF / state 40 (CM848 resets in the caller instead); CM848's fuel_demand_filter_dimension (0x40aee6) is that MTMPRPFL record 'max torque at current rpm in foot-pounds'. "
         "0x1c03c cm550_diagnosticFuelLimitInterpolator is the final fueling arbitration against the group 2 minimum with the master / slave override 32 (inline in CM848's cm848_arbitrateRequestedFueling). 0x1c308 cm550_FUN_0001c308 is the start-up initializer of the torque limit (0xFFFF / 40; jsr at 0x28972). "
         "Timing: 0x17cf0 cm550_engineModeTransitionStateUpdater is the cranking step of the timing chain (TSOI = CKTA 0x80d09a, state 5, TSSTIC = 0); 0xc2be is the AFC timing advance calculation; 0x30b62 vp44InjectionSystemStateController is the final timing selection (states 10 / 9 / 8 / 7, user override timing 0x804024 = e2m 125D +0 TSUOTA in the EEPROM mirror); 0x1c65e cm550_fuelDemandTableBlendCalculator is the 4D timing and looks like the twin of cm848_calculateFourDimensionalInjectionTiming 0x1e870 (user commanded timing with state 2 at 0x1c68c, map blend with state 0 at 0x1c76a, the user increment with TSSTIC = 1 at 0x1c794, copy to TSOI); 0x26ab8 is the misfire table lookup (counterpart of cm848_calculateInjectionTimingMainMisfireLimit 0x29e50); 0x34cc4 / 0x34d52 compute the wet stack timing (0x34cc4 is named vp44_liftPumpFuelDeliveryController). "
         "A timing state enum for 0x80d348 / 0x80d34c / 0x8036e2 is ready from the stores: 0 FOUR_D (0x1c76a), 1 WETSTACK / 13 WTSTCOOL (0x34d3c / 0x34d48), 2 USERCOMD (0x1c68c), 3 ANC (0xb4e8), 4 MAX (0x30b2a), 5 CRANK (0x17d1a), 7 USEROVRD (0x30bd4), 8 STOP (0x30bba), 9 OVERSPED (0x30baa), 10 SHUTDOWN (0x30b96), 11 MISFIRE (0x26b30) - the labels are in the CHR e2m (SOI_State / Final_Timing_State); CM848 splits the same numbering into INJECTION_TIMING_INTERMEDIATE_SOURCE and MAIN_INJECTION_TIMING_SOURCE. TSSTIC bits: 1 user increment, 4 AFC advance, 8 cylinder pressure maintenance. "
         "Warmup protection: 0x16dd4 cm550_highRpmEngineProtectionStateMachine is the engine warmup protection state machine and 0x1709e cm550_fuelTemperatureLimitingSecondary its start-up initializer; 0x80ccc8 (11EA +16 WPIHFG) and 0x80ccca (11EA +18 WPACFT) have no rows. "
         "Hour meters: 0x3452a cm550_FUN_0003452a loads both meters from the EEPROM mirror (0x803b3e / 0x803b50) and looks like the twin of cm848_loadHourMetersFromEeprom 0x5067bc. "
         "MID-BODY ROWS (no jsr / bsr / pointer reaches the address): 0x1ca5c vp44_canPinVp44StatusController, 0x2659a vp44_initVP44StatusFlags, 0x26b00 vp44OperatingConditionChecker, 0x3061a cm550_fuelLimitRestoreFromCapture, 0x30a64 cm550_protectionFlagAccumulator, 0x34534 cm550_initLoopCounter. The batch table's second caller of 0x1ca54 (vp44_evenPhaseSchedulerTaskSet 0x1b62a) is such a row inside the task set 0x1b612; there is one call (jsr at 0x1b63c). "
         "GLOBAL JUDGMENT CALLS. 0x80d284: the present name engine_protection_fuel_limit follows the record's words; fault_derate_fuel_limit is proposed only to match CM848 and the 10B1 +E neighbour. 0x80da50 / 0x80da62 get datalink_ names because J1922 handlers write them too, while the limiter keeps Tsc1 (it stamps member 20 and is CM848's twin). 0x80decc gets a neutral name; CM848's fuel_pressure_fault_fuel_limit_working is the same record. "
         "The rows 0x80a98e / 0x80a992 / 0x80a996 / 0x80a99a carry names from 107C +22.. (ASQ*), but those offsets run past block 107C into 107A (ASRFST, ASDPGN01, ASTH01DP, ASSLDP); only 0x80a98e is proposed here. JCPSDB 0x80da58 (10E8 +C JCOMM progressive shift disable) is named engine_brake_override_flag. "
         "COMMENT WORDING. The plate comments and the enum comments use the proposed global names, some of them at medium confidence (fault_derate_fuel_limit, datalink_engine_control_mode, datalink_torque_limit_fueling, fuel_system_derate_fuel_limit, wet_stack_timing_state, the trip and idle adjustment copies): if a rename is rejected its name in those comments must be put back. The CM848 absence claims were checked by mnemonic in the labelled e2m CHR_CC_11.45.01.07 (the block numbers differ between the two e2m families, so a silent block lookup proves nothing) and by address in both images and the decompilation. "
         "SCORED CANDIDATES: 0x1ce58 -> 0x1f318 and 0x2d9a8 -> 0x2a918 verified (twins, the CM848 functions under their old names); 0xc2ee -> 0x37f28 (cm848_monitorChargingSystemVoltageHighAndLow) and 0x1ca54 -> 0x6ab8 (mpc555_sciPollDuringEepromWrite) rejected. "
         "Scratch: /home/linux/.claude/jobs/374b0424/tmp/w15/r93/scratch/F1/investigator/ (notes_f1.txt, disasm_*.txt, scan_*.py and their outputs, eec1_jump_table.py, find_refs.py, dump_values.py, build_result.py, result_f1.json).")

result = {"batch": "F1", "summary": summary, "functions": functions, "skipped": skipped, "globals": globals_,
          "enum_members": enum_members, "notes": notes}

# ---- checks
seen = [f["address"] for f in functions] + [s["address"] for s in skipped]
assert sorted(seen) == sorted(BATCH), (set(BATCH) - set(seen), set(seen) - set(BATCH))
assert len(seen) == len(set(seen))


def names(path, col=1):
    out = set()
    for row in csv.reader(open(path, errors="replace")):
        if len(row) > col and row[0].startswith("0x"):
            out.add(row[col])
    return out


f550 = names(FROZEN + "cm550/function_renames.csv")
f848 = names(FROZEN + "cm848/function_renames.csv")
g550 = names(FROZEN + "cm550/global_variables.csv")
g848 = names(FROZEN + "cm848/global_variables.csv")
props = [f["proposed_name"] for f in functions]
assert len(props) == len(set(props)), "duplicate function proposal"
for f in functions:
    assert f["current_name"] in f550, f["current_name"]
    if f["proposed_name"] != f["current_name"]:
        assert f["proposed_name"] not in f550, f["proposed_name"]
        assert f["proposed_name"] not in f848, f["proposed_name"]
    if f["cm848_current_name"]:
        assert f["cm848_current_name"] in f848, f["cm848_current_name"]
    if f["relation"] == "twin":
        assert not f["proposed_name"].startswith(("cm550_", "vp44_", "mc68k_")), f["proposed_name"]
    else:
        assert f["proposed_name"].startswith(("cm550_", "vp44_", "mc68k_")), f["proposed_name"]
gprops = [g["proposed_name"] for g in globals_]
assert len(gprops) == len(set(gprops)), "duplicate global proposal"
gaddr = [g["address"] for g in globals_]
assert len(gaddr) == len(set(gaddr)), "duplicate global address"
rows550 = {}
for row in csv.reader(open(FROZEN + "cm550/global_variables.csv", errors="replace")):
    if row and row[0].startswith("0x"):
        rows550[row[0].lower()] = row[1]
for g in globals_:
    assert g["proposed_name"] not in g550, g["proposed_name"]
    assert g["proposed_name"] not in f550, g["proposed_name"]
    have = rows550.get(g["address"].lower(), "")
    assert have == g["current_name"], (g["address"], have, g["current_name"])
    if g["proposed_name"].endswith("_cal"):
        assert 0x803B0A <= int(g["address"], 16) <= 0x804155, g["address"]
    else:
        assert not (0x803B0A <= int(g["address"], 16) <= 0x804155), g["address"]
e550 = {}
for row in csv.reader(open(FROZEN + "cm550/enums.csv", errors="replace")):
    if len(row) > 2 and row[0] == "FUELING_STATE":
        e550[int(row[1], 0)] = row[2]
e848 = {}
for row in csv.reader(open(FROZEN + "cm848/enums.csv", errors="replace")):
    if len(row) > 2 and row[0] == "FUELING_STATE":
        e848[int(row[1], 0)] = row[2]
for e in enum_members:
    if e["firmware"] in ("CM550", "both"):
        assert e550[e["value"]] == e["current_member"], (e["value"], e550[e["value"]])
    if e["firmware"] == "both":
        assert e848[e["value"]] == e["current_member"], (e["value"], e848[e["value"]])
    if e["proposed_member"] != e["current_member"]:
        assert e["proposed_member"] not in e550.values() and e["proposed_member"] not in e848.values()
json.dump(result, open(OUT, "w"), indent=1)
print("ok", len(functions), "functions,", len(skipped), "skipped,", len(globals_), "globals,", len(enum_members), "enum members")
print("bytes", len(json.dumps(result)))
